--
-- Name: sample; Type: TABLE; Schema: clinlims; Owner: clinlims
--

CREATE TABLE clinlims.sample (
    id numeric(10,0) NOT NULL,
    accession_number character varying(20) NOT NULL,
    package_id numeric(10,0),
    domain character varying(1),
    next_item_sequence numeric(10,0),
    revision numeric,
    entered_date timestamp without time zone NOT NULL,
    received_date timestamp without time zone NOT NULL,
    collection_date timestamp without time zone,
    client_reference character varying(20),
    status character varying(1),
    released_date timestamp without time zone,
    sticker_rcvd_flag character varying(1),
    sys_user_id numeric(10,0),
    barcode character varying(20),
    transmission_date timestamp without time zone,
    lastupdated timestamp(6) without time zone,
    spec_or_isolate character varying(1),
    priority numeric(1,0),
    status_id numeric(10,0),
    referring_id character varying(50),
    clinical_order_id numeric(10,0),
    is_confirmation boolean DEFAULT false NOT NULL,
    fhir_uuid uuid,
    order_priority character varying(255) DEFAULT 'ROUTINE'::character varying,
    gps_latitude numeric(9,6),
    gps_longitude numeric(9,6),
    gps_accuracy_meters integer,
    gps_capture_method character varying(10),
    gps_capture_timestamp timestamp without time zone,
    CONSTRAINT chk_gps_accuracy_positive CHECK (((gps_accuracy_meters IS NULL) OR (gps_accuracy_meters > 0))),
    CONSTRAINT chk_gps_capture_method_values CHECK (((gps_capture_method IS NULL) OR ((gps_capture_method)::text = ANY ((ARRAY['AUTO'::character varying, 'MANUAL'::character varying])::text[])))),
    CONSTRAINT chk_gps_coordinate_consistency CHECK ((((gps_latitude IS NULL) AND (gps_longitude IS NULL)) OR ((gps_latitude IS NOT NULL) AND (gps_longitude IS NOT NULL)))),
    CONSTRAINT chk_gps_latitude_range CHECK (((gps_latitude IS NULL) OR ((gps_latitude >= ('-90'::integer)::numeric) AND (gps_latitude <= (90)::numeric)))),
    CONSTRAINT chk_gps_longitude_range CHECK (((gps_longitude IS NULL) OR ((gps_longitude >= ('-180'::integer)::numeric) AND (gps_longitude <= (180)::numeric))))
);


ALTER TABLE clinlims.sample OWNER TO clinlims;

