--
-- Name: sample_storage_movement; Type: TABLE; Schema: clinlims; Owner: clinlims
--

CREATE TABLE clinlims.sample_storage_movement (
    id numeric(10,0) NOT NULL,
    sample_item_id numeric(10,0) NOT NULL,
    previous_location_id numeric(10,0),
    previous_location_type character varying(20),
    previous_position_coordinate character varying(50),
    new_location_id numeric(10,0),
    new_location_type character varying(20),
    new_position_coordinate character varying(50),
    moved_by_user_id numeric(10,0) NOT NULL,
    movement_date timestamp without time zone DEFAULT now() NOT NULL,
    reason text,
    last_updated timestamp without time zone,
    CONSTRAINT chk_movement_has_location CHECK ((((previous_location_id IS NOT NULL) AND (previous_location_type IS NOT NULL)) OR ((new_location_id IS NOT NULL) AND (new_location_type IS NOT NULL)))),
    CONSTRAINT chk_new_location_type_valid CHECK (((new_location_type IS NULL) OR ((new_location_type)::text = ANY ((ARRAY['device'::character varying, 'shelf'::character varying, 'rack'::character varying, 'box'::character varying])::text[])))),
    CONSTRAINT chk_previous_location_type_valid CHECK (((previous_location_type IS NULL) OR ((previous_location_type)::text = ANY ((ARRAY['device'::character varying, 'shelf'::character varying, 'rack'::character varying, 'box'::character varying])::text[]))))
);


